def q_update(q, reward, gamma, next_max, alpha):
    """Return Q(s, a) after one Q-learning update."""
    return q + alpha * (reward + gamma * next_max)

tests_py:
def test_known_value():
    got = solution.q_update(0.5, 1.0, 0.9, 0.8, 0.1)
    assert abs(got - 0.622) < 1e-12

def test_moves_toward_target():
    q = 0.5
    target = 1.0 + 0.9 * 0.8
    assert q < solution.q_update(q, 1.0, 0.9, 0.8, 0.1) < target

def test_alpha_one_reaches_target():
    assert abs(solution.q_update(0.5, 1.0, 0.9, 0.8, 1.0) - 1.72) < 1e-12

def test_alpha_zero_unchanged():
    assert solution.q_update(0.7, 2.0, 0.9, 5.0, 0.0) == 0.7

def test_terminal_no_bootstrap():
    assert abs(solution.q_update(0.5, 1.0, 0.9, None, 0.5) - 0.75) < 1e-12

def test_invalid_alpha():
    try:
        solution.q_update(0.5, 1.0, 0.9, 0.8, 1.5)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_returns_float():
    assert isinstance(solution.q_update(1, 1, 0.9, 1, 0.5), float)
